id =#{entity.id}

	,`name` = #{entity.name}


	,`org_id` = #{entity.orgId}


	,phone = #{entity.phone}


	,user_type = #{entity.userType}


	,sex = #{entity.sex}


	,email =#{entity.email}


	,dev_user_type= #{entity.devUserType}


	,user_type= #{entity.userType}


	,avatar= #{entity.avatar}


	,birthday= #{entity.birthday}


	,password= #{entity.password}


	,registered_email= #{entity.registeredEmail}


	,registered_phone= #{entity.registeredPhone}


	,openid= #{entity.openid}


	,unionid= #{entity.unionid}


   where id=#{entity.id}

mapper.select:
select

from t_sys_user where t_sys_user.account = #{account} and delete_flag = 0

	and t_sys_user.org_id = #{orgId}

select

from t_sys_user
where t_sys_user.phone = #{phone}

select

from t_sys_user
where t_sys_user.email = #{email}

SELECT
FROM t_sys_user LEFT JOIN t_sys_org on t_sys_org.id = t_sys_user.org_id WHERE t_sys_user.account = #{account} and org_code = #{orgCode}
AND delete_flag = 0

SELECT
FROM t_sys_user WHERE ( t_sys_user.account = #{account} or (t_sys_user.phone = #{account}) or (t_sys_user.email = #{account}) ) AND delete_flag = 0
and t_sys_user.tenant_org_id = #{tenantOrgId}

SELECT
FROM t_sys_user LEFT JOIN t_sys_org on t_sys_org.id = t_sys_user.org_id WHERE t_sys_user.account = #{account} and t_sys_org.id = #{orgId}
AND delete_flag = 0

select

from t_sys_user
where delete_flag = 0

	and account = #{account}


	and  email = #{email}


	and  phone = #{phone}

select * from t_sys_user where

( org_id
in (
select chi.id
from t_sys_org fa LEFT JOIN t_sys_org chi
on fa.left_num<chi.left_num and fa.right_num> chi.right_num
where fa.id=#{orgId}
)or t_sys_user.org_id=#{orgId}
)
and t_sys_user.account=#{account}
;

SELECT t_sys_user.*
FROM t_sys_user left join t_tenant on ( t_sys_user.org_id
IN ( SELECT c.id FROM t_sys_org f LEFT JOIN t_sys_org c ON ( f.left_num <= c.left_num AND c.right_num <= f.right_num ) WHERE f.id = t_tenant.org_id )) left join t_saas_contract on t_saas_contract.id = t_tenant.contract_id left join t_saas_contract_template template on template.id = t_saas_contract.contract_template_id left join t_saas_application_example on t_saas_application_example.contract_template_id = template.id WHERE t_saas_application_example.domain = #{domain} and t_sys_user.account = #{account}
